  ('46ae90f9-ee91-460a-ac37-8fdf6ad2cd75', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'c3c25d97-e9eb-42d9-8082-d0bddaaa27f0', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहानुभूति चाहिए, महाविभूति है यही_ वशीकृता सदैव है बनी हुई स्वयं मही।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-931Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a1a7cf25-d814-4b1c-9fc0-2b45a091cea5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'c3c25d97-e9eb-42d9-8082-d0bddaaa27f0', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$विरुद्धवाद बुद्ध का दया-प्रवाह में बहा, विनित लोकवर्ग क्या न सामने झुका रहा? अहा! वही उदार है परोपकार जो करे, वही मनुष्य है कि जो मनुष्य के लिए मरे। रहो न भूल के कभी मदांध तुच्छ वित्त में, सनाथ जान आपको करो न गर्व चित्त में। अनाथ कौन है यहाँ? त्रिलोकनाथ साथ हैं, दयालु दीनबंधु के बड़े विशाल हाथ हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-931Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('a09f70be-6a8f-405c-b8ec-f14fab54c570', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'c3c25d97-e9eb-42d9-8082-d0bddaaa27f0', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अतीव भाग्यहीन है अधीर भाव जो करे, वही मनुष्य है कि जो मनुष्य के लिए मरे। अनंत अंतरिक्ष में अनंत देव हैं खड़े, समक्ष ही स्वाबाहु जो बढ़ा रहे बड़े-बड़े। परस्परावलंब से उठो तथा बढ़ो सभी, अभी अमर्त्य-अंक में अपंक हो चढ़ो सभी। रहो न यों कि एक से न काम और का सरे, वही मनुष्य है कि जो मनुष्य के लिए मरे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-931Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('bda906c2-ffed-45b5-966a-431819f4f4be', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'c3c25d97-e9eb-42d9-8082-d0bddaaa27f0', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मनुष्य मात्र बंधु है' यही बड़ा विवेक है, पुराणपुरुष स्वयंभू पिता प्रसिद्ध एक है। फलानुसार कर्म के अवश्य बाह्य भेद हैं, परंतु अंतरैक्य में प्रमाणभूत वेद हैं। अनर्थ है कि बंधु ही न बंधु की व्यथा हरे, वही मनुष्य है कि जो मनुष्य के लिए मरे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-931Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('19e9bd15-a271-4ab9-b5e3-a117aef1e6eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'c3c25d97-e9eb-42d9-8082-d0bddaaa27f0', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चलो अभीष्ट मार्ग में सहर्ष खेलते हुए, विपत्ति, विघ्न जो पड़ें उन्हें ढकेलते हुए। घटे न हेयमेल हाँ, बढ़े न भिन्नता कभी, अतर्क एक पंथ के सतरक पंथ हों सभी। तभी समर्थ भाव है कि तारता हुआ तरे, वही मनुष्य है कि जो मनुष्य के लिए मरे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-47-931Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
